// OTHVM — Voice Tool: تجهيز الملف الصوتي (اسم وميْم مناسبين لخدمة التفريغ + base64 لمساري Gemini)
const item = $input.first() || { json: {} };
const j = item.json || {};
if (item.binary && item.binary.data) {
  const b = item.binary.data;
  b.fileName = 'voice.ogg';
  b.fileExtension = 'ogg';
  if (!b.mimeType) b.mimeType = 'audio/ogg';
  delete j.error;
  let audio_base64 = '';
  try {
    const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
    audio_base64 = buf.toString('base64');
  } catch (e) {
    return [{ json: { ok: false, error: 'تعذر تجهيز الملف للتفريغ: ' + String(e.message || e).slice(0, 200) } }];
  }
  return [{ json: { ok: true, audio_base64: audio_base64, audio_mime: b.mimeType || 'audio/ogg' }, binary: item.binary }];
}
const e = j.error;
const msg = typeof e === 'string' ? e : (e && typeof e === 'object' ? ([e.message, e.description].filter(Boolean).join(' — ') || 'فشل تنزيل الملف من تلجرام') : 'فشل تنزيل الملف الصوتي من تلجرام');
return [{ json: { ok: false, error: String(msg).slice(0, 300) } }];

// OTHVM — Voice Tool: تقييم جودة التفريغ (verbose_json) + تجهيز رسالة الصدى للمؤسس
const j = ($input.first() || {}).json || {};
const errOf = (x) => {
  if (!x) return '';
  if (typeof x === 'string') return x;
  if (typeof x === 'object') return [x.message, x.description].filter(Boolean).join(' — ') || JSON.stringify(x).slice(0, 200);
  return String(x);
};
let inp = {};
try { inp = $('Input').first().json || {}; } catch (e) { inp = {}; }
const carry = {};
if (inp.reply_to_message_id !== undefined && inp.reply_to_message_id !== null && inp.reply_to_message_id !== '' && !isNaN(Number(inp.reply_to_message_id))) carry.reply_to_message_id = Number(inp.reply_to_message_id);
if (inp.chat_id !== undefined && inp.chat_id !== null && String(inp.chat_id).trim()) carry.chat_id = String(inp.chat_id).trim();
if (j.ok === false) return [{ json: Object.assign({ ok: false, error: String(j.error || 'فشل غير معروف').slice(0, 300) }, carry) }];
if (j.error) return [{ json: Object.assign({ ok: false, error: String(errOf(j.error) || 'فشل غير معروف').slice(0, 300) }, carry) }];
const text = typeof j.text === 'string' ? j.text.trim() : '';
if (!text) return [{ json: Object.assign({ ok: false, error: 'التفريغ رجع فاضي — يمكن مفيش كلام مفهوم في التسجيل' }, carry) }];
const segs = Array.isArray(j.segments) ? j.segments : [];
let maxNsp = 0;
let minAlp = 0;
let maxEnd = 0;
for (const s of segs) {
  if (s && typeof s.no_speech_prob === 'number' && s.no_speech_prob > maxNsp) maxNsp = s.no_speech_prob;
  if (s && typeof s.avg_logprob === 'number' && s.avg_logprob < minAlp) minAlp = s.avg_logprob;
  if (s && typeof s.end === 'number' && s.end > maxEnd) maxEnd = s.end;
}
const norm = text.toLowerCase().replace(/[\u064B-\u0652]/g, '').replace(/[.!،,?؟\s"'«»…\-_]+/g, ' ').trim();
const short = norm.length <= 60;
const asrStock = short && (norm.indexOf('thank you for watching') !== -1 || norm.indexOf('thanks for watching') !== -1 || norm.indexOf('subscribe') !== -1);
const stockExact = ['شكرا للمشاهدة', 'ترجمة نانسي قنقر', 'لا تنسوا الاشتراك في القناة', 'لا تنسى الاشتراك في القناة', 'اشترك في القناة', 'المزيد من الفيديوهات'].indexOf(norm) !== -1;
if (asrStock || stockExact) return [{ json: Object.assign({ ok: false, error: 'التسجيل مش فيه كلام واضح — يمكن فاضي أو ضوضاء. اطلب من المستخدم يبعت التسجيل تاني أو يكتب الرسالة.' }, carry) }];
const dur = typeof j.duration === 'number' ? j.duration : 0;
const overrun = dur > 0 && maxEnd > dur + 5;
const uncertain = maxNsp > 0.6 || minAlp < -1.2 || overrun;
let plain = text.replace(/\s+/g, ' ');
if (plain.length > 900) plain = plain.slice(0, 900) + '…';
const echo = (uncertain ? '🎙️ سمعت كده (مش متأكد قوي): "' : '🎙️ فهمت: "') + plain + '"';
const out = Object.assign({ ok: true, text: text, uncertain: uncertain, echo: echo }, carry);
if (typeof j.language === 'string' && j.language) out.language = j.language;
return [{ json: out }];

// OTHVM — Voice Tool: هل رسالة الفويس المصدر لسه موجودة؟ (فشل الفحص = بنفترض موجودة — مش بنعطّل)
const a = (() => { try { return $('Assess').first().json || {}; } catch (e) { return {}; } })();
const p = ($input.first() || {}).json || {};
const parts = [p.description, p.message, (p.error && (p.error.description || p.error.message)) || (typeof p.error === 'string' ? p.error : (p.error ? JSON.stringify(p.error) : ''))].filter(Boolean).map(String).join(' | ');
const del = /message to react not found|message not found/i.test(parts);
return [{ json: Object.assign({}, a, { sourceDeleted: del }) }];

// OTHVM — Voice Tool: المخرجات النهائية للأجنت {ok, text, language, uncertain} أو {ok:false, error} أو {ok:true, deleted:true}
const cur = ($input.first() || {}).json || {};
if (cur.deleted === true) return [{ json: { ok: true, deleted: true, note: cur.note || 'الفويس اتمسح' } }];
let a = null;
try { a = $('Assess').first().json; } catch (e) { a = null; }
if (!a) a = ($input.first() || {}).json || {};
if (a.ok === false) return [{ json: { ok: false, error: String(a.error || 'فشل غير معروف').slice(0, 300) } }];
const out = { ok: true, text: a.text };
if (a.language) out.language = a.language;
out.uncertain = a.uncertain === true;
return [{ json: out }];

// OTHVM — Gemini audio fallback: extract transcript text.
const j = ($input.first() || {}).json || {};
if (j.error) {
  const e = j.error;
  const msg = typeof e === 'string' ? e : [e.message, e.description].filter(Boolean).join(' — ') || JSON.stringify(e).slice(0, 300);
  return [{ json: { ok: false, error: 'Groq failed and Gemini fallback failed: ' + String(msg).slice(0, 400) } }];
}
let text = '';
try {
  text = (((j.candidates || [])[0] || {}).content?.parts || []).map((p) => p.text || '').join('').trim();
} catch (e) { text = ''; }
if (!text) return [{ json: { ok: false, error: 'Groq failed and Gemini returned no transcript' } }];
return [{ json: { ok: true, text, language: '', duration: 0 } }];
